// Campaign "The Lost Crown": five quests as DATA (goals §7).
//
// What lives here:
//   - metadata the SERVER needs (durations, gag ids) -> it picks gags and times phases from these;
//   - the beat scripts the TV plays (see shared/cutscene-ops.js for the op contract).
//
// STATUS: every quest has all 4 fail gags + a success ending, and they all validate and play.
// The beats below are generated by `scaffold()` from the per-gag hints (placeholder choreography:
// captions, camera, a culprit animation, FX, freeze-frame, reaction shot). The real, hand-authored
// choreography replaces a quest's beats by setting `beats` / `beats.fail[gagId]` directly.
// See docs/CUTSCENES.md for the authoring guide.
import { validateQuestScripts } from './cutscene-ops.js';

const SEGMENT_DEFAULTS = { setup: 5, approach: 7, moment: 3, success: 5 };

/** Placeholder choreography builder. Marks used: start, mid, goal, spot (every scene defines them). */
function scaffold(q) {
  const beats = {
    setup: [
      { t: 0, op: 'camera', shot: 'wide', dur: 5 },
      { t: 0.2, op: "caption", text: "{intro}", dur: 4.3 },
      { t: 0.4, op: 'formation', name: 'line', center: 'start', walk: true, dur: 3.6 },
      { t: 3.8, op: 'banner', who: 'team:all', dur: 1.2 },
    ],
    approach: [
      { t: 0, op: 'camera', shot: 'follow', target: 'lead', dur: 7, dist: 7 },
      { t: 0.3, op: 'caption', text: q.approach, dur: 4 },
      { t: 0.3, op: 'formation', name: 'column', center: 'mid', walk: true, dur: 6.4 },
    ],
    moment: [
      { t: 0, op: 'music', track: 'stop' },
      { t: 0.1, op: 'sfx', name: 'stinger' },
      { t: 0.1, op: 'camera', shot: 'pushIn', target: 'lead', dur: 2.8 },
      { t: 0.3, op: 'caption', text: q.moment, dur: 2.4 },
      { t: 0.5, op: 'play', who: 'team:all', anim: 'Idle', loop: true },
    ],
    success: [
      { t: 0, op: 'camera', shot: 'lowAngle', target: 'hero', dur: 3 },
      { t: 0.1, op: 'play', who: 'hero', anim: q.heroAnim || 'Interact' },
      { t: 0.2, op: 'sfx', name: 'fanfare' },
      { t: 0.4, op: 'caption', text: q.success, dur: 3.5 },
      { t: 0.6, op: 'fx', kind: 'sparkle', at: 'hero', count: 24 },
      { t: 2.2, op: 'camera', shot: 'wide', dur: 2.8 },
      { t: 2.4, op: 'play', who: 'team:others', anim: 'Cheer' },
      { t: 2.6, op: 'banner', who: 'hero', text: '{hero}', dur: 2 },
    ],
    fail: {},
  };
  for (const g of q.gags) {
    const D = g.duration;
    beats.fail[g.id] = [
      { t: 0, op: 'camera', shot: 'closeUp', target: 'culprit', dur: 2.5 },
      { t: 0.1, op: 'caption', text: g.caption, dur: 2.8 },
      { t: 0.2, op: 'play', who: 'culprit', anim: g.anim || 'Interact' },
      { t: 1.2, op: 'sfx', name: g.sfx || 'thud' },
      { t: 1.3, op: 'fx', kind: g.fx || 'dust', at: 'culprit', count: 18 },
      { t: 2.3, op: 'play', who: 'culprit', anim: 'Cheer' }, // oblivious pride
      { t: 2.6, op: 'camera', shot: 'wide', dur: 1.4 },
      { t: 3.0, op: 'freeze', dur: 1.2 },
      { t: 4.3, op: 'caption', text: q.consequence, dur: 2 },
      { t: 4.3, op: 'camera', shot: 'shake', intensity: 0.5, dur: 1 },
      { t: 4.4, op: 'sfx', name: 'wahwah' },
      { t: 4.4, op: 'play', who: 'team:others', anim: 'Hit_B' },
      { t: Math.min(D - 1.2, 5.4), op: 'camera', shot: 'closeUp', target: 'team:others', dur: 1 },
      { t: Math.min(D - 1.2, 5.4), op: 'lookAt', who: 'team:others', at: 'culprit', dur: 0.8 },
    ];
  }
  return beats;
}

const gag = (id, name, caption, extra = {}) => ({ id, name, caption, duration: 7, ...extra });

