export const QUESTS = RAW.map((q, index) => {
  const quest = { index, durations: { ...SEGMENT_DEFAULTS }, sceneIds: [], ...q };
  quest.beats = quest.beats || scaffold(quest);
  return quest;
});

export const CAMPAIGN = { id: 'lost-crown', name: 'The Lost Crown', quests: QUESTS };

export const getQuest = (i) => QUESTS[i];
export const getQuestById = (id) => QUESTS.find((q) => q.id === id);

/** Throws if any quest script is invalid. Called at server boot. */
export function assertCampaignValid() {
  const errs = QUESTS.flatMap(validateQuestScripts);
  if (errs.length) throw new Error(`Campaign scripts invalid:\n${errs.join('\n')}`);
}
